import re

def parse_tree():
    with open("/app/dataset/genealogy_trees.txt", "r") as f:
        lines = [line.rstrip("\r\n") for line in f]

    # Find all boxes
    # A box is defined by a top horizontal line, vertical sides, and a bottom horizontal line.
    # Let us scan the grid and find all potential boxes.
    num_rows = len(lines)
    max_cols = max(len(l) for l in lines)
    grid = []
    for l in lines:
        grid.append(l + " " * (max_cols - len(l)))

    # Detect horizontal boundaries: characters in ['-', '~', '+', '_', '│', '|', '┌', '┐', '└', '┘'] etc.
    # To find boxes, we can look for corners or vertical lines.
    # Let us find all box candidates.
    # A box starts at (r1, c1) and ends at (r2, c2).
    # Side boundaries are usually '|' or '│' at c1 and c2.
    # Top and bottom boundaries are lines of horizontal chars.
    boxes = []
    visited = set()

    # Let us iterate over all cells to find the top-left corner of a box
    # A top-left corner has a box boundary char, and we can find the rectangular box.
    # Or more simply: since names are unique and contained in boxes, let us find all name boxes.
    # Let us look for vertical boundaries:
    # A vertical line at column c from row r1 to r2.
    # Let us detect all rectangles of the form:
    # r1, r2, c1, c2 where:
    # - c1 < c2
    # - r1 < r2
    # - grid[r][c1] and grid[r][c2] are in ['|', '│', '+'] for r in [r1, r2]
    # - top and bottom are mostly non-empty horizontal-like chars
    # Let us write a robust finder:
    for r1 in range(num_rows):
        for c1 in range(max_cols):
            if grid[r1][c1] in ['+', '│', '|', '┌', '└']:
                # Search for c2
                for c2 in range(c1 + 4, min(c1 + 50, max_cols)):
                    if grid[r1][c2] in ['+', '│', '|', '┐', '┘']:
                        # Search for r2
                        for r2 in range(r1 + 2, min(r1 + 10, num_rows)):
                            if grid[r2][c1] in ['+', '│', '|', '└', '┌'] and grid[r2][c2] in ['+', '│', '|', '┘', '┐']:
                                # Check if sides are vertical boundaries
                                is_box = True
                                for r in range(r1 + 1, r2):
                                    if grid[r][c1] not in ['|', '│'] or grid[r][c2] not in ['|', '│']:
                                        is_box = False
                                        break
                                if not is_box:
                                    continue
                                # Check if top and bottom are horizontal boundaries
                                # Horizontal boundaries contain '-', '~', '+', '_', etc.
                                for c in range(c1 + 1, c2):
                                    if grid[r1][c] == ' ' or grid[r2][c] == ' ':
                                        is_box = False
                                        break
                                if not is_box:
                                    continue

                                # Extract name
                                name_lines = []
                                for r in range(r1 + 1, r2):
                                    content = grid[r][c1+1:c2].strip()
                                    if content:
                                        # remove any internal boundary noise if any
                                        name_lines.append(content)
                                name = " ".join(name_lines)
                                # clean up name (remove spaces, etc.)
                                name = re.sub(r'\s+', ' ', name).strip()
                                # Only accept if name contains alphabetical chars
                                if any(c.isalpha() for c in name):
                                    # Check if this box is already found (or subset)
                                    box_id = (r1, r2, c1, c2)
                                    # Avoid duplicates
                                    overlap = False
                                    for b in boxes:
                                        if b['r1'] <= r1 <= b['r2'] and b['c1'] <= c1 <= b['c2']:
                                            overlap = True
                                            break
                                    if not overlap:
                                        boxes.append({
                                            'name': name,
                                            'r1': r1, 'r2': r2, 'c1': c1, 'c2': c2
                                        })

    print(f"Detected {len(boxes)} boxes.")
    for b in sorted(boxes, key=lambda x: (x['r1'], x['c1']))[:10]:
        print(f"Name: {b['name']} at ({b['r1']},{b['c1']}) to ({b['r2']},{b['c2']})")

    # Now let's trace parent-child connections.
    # To trace robustly, let's define a function to check if there is a vertical path between two points.
    # A vertical path exists from (r_start, c) to (r_end, c) if we can traverse down/up.
    # Due to fragmentation, we allow small horizontal offsets or gaps.
    def get_vertical_line_cols(r, c_min, c_max):
        # returns list of columns on row r that have vertical characters or are connected
        cols = []
        for c in range(c_min, c_max + 1):
            if grid[r][c] in ['|', '│', '+', '/']:
                cols.append(c)
        return cols

    # Let's map each box to its parent.
    # A box has a top connection point (around its horizontal center, usually).
    # Let's trace UP from the box top.
    # The box top is at r1. The connection is at some column c in [c1, c2].
    # Let's find vertical lines on r1-1, r1-2, etc. that are near the box columns.
    # Then we follow them up to a horizontal line or another box.
    # Let's write a general path tracer!
    # Instead of full path tracing, let's find the vertical lines directly.
    # A horizontal line is a continuous/semi-continuous line of horizontal characters.
    # Let's identify all horizontal lines.
    # A horizontal line is a set of points (r, c) on the same row r, which are connected.
    # Let's group connected horizontal line characters.
    # Two horizontal line chars on row r at c and c' are connected if there is no gap of > 5 spaces.
    h_lines = []
    for r in range(num_rows):
        # find all non-space segments on row r
        row = grid[r]
        segments = []
        curr_seg = []
        for c in range(max_cols):
            is_h = row[c] in ['-', '~', '+', '_', '┌', '┐', '└', '┘', '┬', '┴', '┼']
            # also allow other non-space chars except vertical-only ones, or allow any non-space for simplicity
            if row[c] != ' ' and row[c] not in ['|', '│']:
                if not curr_seg:
                    curr_seg = [c, c]
                else:
                    curr_seg[1] = c
            else:
                if curr_seg:
                    # check if the gap is small
                    # we will close the segment later if gap is small
                    segments.append(curr_seg)
                    curr_seg = []
        if curr_seg:
            segments.append(curr_seg)

        # Merge segments with gap <= 5
        merged = []
        for seg in segments:
            if not merged:
                merged.append(seg)
            else:
                last = merged[-1]
                if seg[0] - last[1] <= 5:
                    last[1] = seg[1]
                else:
                    merged.append(seg)
        for start, end in merged:
            if end - start >= 5: # only keep significant horizontal lines
                h_lines.append({'r': r, 'c1': start, 'c2': end})

    print(f"Detected {len(h_lines)} horizontal lines.")

    # Now let's trace connections between boxes.
    # For each box, we can go down to find children, or go up to find parent.
    # Let's define a function to trace down from row r at column c.
    # We want to find which horizontal line or box it hits first.
    def trace_down(r_start, c_start):
        # Traces down from r_start at c_start.
        # We can handle small horizontal drifts.
        c = c_start
        for r in range(r_start, num_rows):
            # Check if we hit a box
            for b in boxes:
                if b['r1'] <= r <= b['r2'] and b['c1'] <= c <= b['c2']:
                    return ('box', b)
            # Check if we hit a horizontal line
            for hl in h_lines:
                if hl['r'] == r and hl['c1'] <= c <= hl['c2']:
                    return ('hline', hl)
            # Try to follow vertical line
            # Look at r, c and its neighbors
            next_c = None
            for offset in [0, -1, 1, -2, 2]:
                if grid[r][c + offset] in ['|', '│', '+', '/']:
                    next_c = c + offset
                    break
            if next_c is not None:
                c = next_c
            else:
                # If we hit spaces, let's see if we can jump a gap of 1-2 rows
                gap_ok = False
                for nr in range(r + 1, min(r + 3, num_rows)):
                    for offset in [0, -1, 1, -2, 2]:
                        if grid[nr][c + offset] in ['|', '│', '+']:
                            c = c + offset
                            r = nr - 1
                            gap_ok = True
                            break
                    if gap_ok:
                        break
                if not gap_ok:
                    return ('none', (r, c))
        return ('none', (num_rows, c))

    def trace_up(r_start, c_start):
        # Traces up from r_start at c_start.
        c = c_start
        for r in range(r_start, -1, -1):
            # Check if we hit a box
            for b in boxes:
                if b['r1'] <= r <= b['r2'] and b['c1'] <= c <= b['c2']:
                    return ('box', b)
            # Check if we hit a horizontal line
            for hl in h_lines:
                if hl['r'] == r and hl['c1'] <= c <= hl['c2']:
                    return ('hline', hl)
            # Try to follow vertical line
            next_c = None
            for offset in [0, -1, 1, -2, 2]:
                if grid[r][c + offset] in ['|', '│', '+', '/']:
                    next_c = c + offset
                    break
            if next_c is not None:
                c = next_c
            else:
                # gap jump
                gap_ok = False
                for nr in range(r - 1, max(-1, r - 3), -1):
                    for offset in [0, -1, 1, -2, 2]:
                        if grid[nr][c + offset] in ['|', '│', '+']:
                            c = c + offset
                            r = nr + 1
                            gap_ok = True
                            break
                    if gap_ok:
                        break
                if not gap_ok:
                    return ('none', (r, c))
        return ('none', (0, c))

    # Let's find children of each box.
    # To find children:
    # 1. Trace down from the bottom of the box (middle column).
    # 2. If we hit a horizontal line HL, then find all vertical lines going down from HL.
    #    For each such vertical line, trace down to find the box it hits.
    # 3. If we hit another box directly, that's a child.
    box_children = {b['name']: [] for b in boxes}
    box_parent = {b['name']: None for b in boxes}

    for b in boxes:
        # Trace down from bottom
        r_bottom = b['r2'] + 1
        c_mid = (b['c1'] + b['c2']) // 2
        res_type, res_obj = trace_down(r_bottom, c_mid)
        if res_type == 'box':
            child = res_obj
            box_children[b['name']].append(child['name'])
            box_parent[child['name']] = b['name']
        elif res_type == 'hline':
            hl = res_obj
            # Find all columns on hl['r'] + 1 that have vertical lines
            # and trace down from them
            r_next = hl['r'] + 1
            for col in range(hl['c1'], hl['c2'] + 1):
                # We want to find start columns of vertical lines going down
                # To avoid duplicate traces for the same line, check if grid[r_next][col] is vertical
                # and it is not immediately preceded by another vertical on r_next (or we group them)
                if grid[r_next][col] in ['|', '│', '+']:
                    # Only trace if it's the start of a vertical line cluster
                    if col == hl['c1'] or grid[r_next][col-1] not in ['|', '│', '+']:
                        c_res_type, c_res_obj = trace_down(r_next, col)
                        if c_res_type == 'box':
                            child = c_res_obj
                            if child['name'] not in box_children[b['name']] and child['name'] != b['name']:
                                box_children[b['name']].append(child['name'])
                                box_parent[child['name']] = b['name']

    # Print family relationships of Dawid Majtyka
    target = 'Dawid Majtyka'
    curr = target
    lineage = []
    while curr:
        lineage.append(curr)
        curr = box_parent.get(curr)
    print(f"\nLineage of {target}: {' -> '.join(lineage)}")

    # Print direct children of Przemysław Kurczab and their grandchildren
    ancestor = 'Przemysław Kurczab'
    if ancestor in box_children:
        print(f"\nChildren of {ancestor}:")
        for child in box_children[ancestor]:
            # find grandchildren
            grandchildren = []
            for ch2 in box_children.get(child, []):
                for gch in box_children.get(ch2, []):
                    grandchildren.append(gch)
            print(f"- {child}: children={box_children.get(child, [])}, grandchildren={grandchildren} (count={len(grandchildren)})")

if __name__ == "__main__":
    parse_tree()

