import re
import csv

def solve():
    with open("/app/dataset/genealogy_trees.txt", "r") as f:
        lines = [line.rstrip("\r\n") for line in f]

    num_rows = len(lines)
    max_cols = max(len(l) for l in lines)
    grid = [l + " " * (max_cols - len(l)) for l in lines]

    # Load people
    people = {}
    with open("/app/dataset/people_accounts.csv", "r") as f:
        reader = csv.reader(f)
        header = next(reader)
        for row in reader:
            if len(row) >= 3:
                first = row[0].strip()
                last = row[1].strip()
                balance = int(row[2].strip())
                people[f"{first} {last}"] = balance

    # Locate all person boxes in the tree
    # We will match the names from CSV to find all boxes in the tree.
    # To be extremely precise, we can find a box for each name in people.
    boxes = []

    # Let's find boxes by searching for all names in the tree
    for name in people:
        first, last = name.split(maxsplit=1)
        # Search for first and last in grid
        for r in range(num_rows):
            line = grid[r]
            if first in line:
                idx = -1
                while True:
                    idx = line.find(first, idx + 1)
                    if idx == -1:
                        break
                    # check last_name proximity
                    for r_offset in [-1, 0, 1]:
                        nr = r + r_offset
                        if 0 <= nr < num_rows:
                            nline = grid[nr]
                            if last in nline:
                                l_idx = nline.find(last)
                                if abs(idx - l_idx) < 15:
                                    # Found coordinates! Now find box boundary columns c1, c2
                                    # We look for '|' or '│' to the left of idx
                                    c1 = idx
                                    while c1 >= 0 and grid[r][c1] not in ['|', '│']:
                                        c1 -= 1
                                    if c1 < 0:
                                        c1 = l_idx
                                        while c1 >= 0 and grid[nr][c1] not in ['|', '│']:
                                            c1 -= 1

                                    # Right boundary c2
                                    c2 = max(idx + len(first), l_idx + len(last))
                                    while c2 < max_cols and grid[r][c2] not in ['|', '│']:
                                        c2 += 1
                                    if c2 >= max_cols:
                                        c2 = max(idx + len(first), l_idx + len(last))
                                        while c2 < max_cols and grid[nr][c2] not in ['|', '│']:
                                            c2 += 1

                                    if c1 >= 0 and c2 < max_cols:
                                        # trace rows up and down for vertical sides
                                        r1 = min(r, nr)
                                        while r1 >= 0 and grid[r1][c1] in ['|', '│']:
                                            r1 -= 1
                                        r2 = max(r, nr)
                                        while r2 < num_rows and grid[r2][c1] in ['|', '│']:
                                            r2 += 1

                                        # Verify r1 and r2 are indeed box bounds (should be top/bottom lines of box)
                                        # The top boundary r1 should have horizontal-like chars
                                        top_h = sum(1 for c in range(c1+1, c2) if grid[r1][c] in ['-', '~', '+', '_'])
                                        bot_h = sum(1 for c in range(c1+1, c2) if grid[r2][c] in ['-', '~', '+', '_'])
                                        width = c2 - c1 - 1
                                        if width > 0 and (top_h / width >= 0.25 and bot_h / width >= 0.25):
                                            # This is a valid box!
                                            box_info = {
                                                'name': name,
                                                'r1': r1, 'r2': r2, 'c1': c1, 'c2': c2
                                            }
                                            # Avoid duplicates
                                            if box_info not in boxes:
                                                boxes.append(box_info)
                                            break
                    else:
                        continue
                    break

    print(f"Total mapped boxes: {len(boxes)}")

    # Function to check if a point is inside any box
    def find_box_at(r, c):
        for b in boxes:
            if b['r1'] <= r <= b['r2'] and b['c1'] <= c <= b['c2']:
                return b
        return None

    # Function to follow a vertical line down to find a child box
    def trace_vertical_line_down(r_start, c_start):
        c = c_start
        for r in range(r_start, num_rows):
            # Check if we are inside any box
            b = find_box_at(r, c)
            if b:
                return b
            # If the current character is a space, let's find the vertical line in nearby columns
            if grid[r][c] not in ['|', '│', '+']:
                next_c = None
                for offset in [1, -1, 2, -2]:
                    if grid[r][c + offset] in ['|', '│', '+']:
                        next_c = c + offset
                        break
                if next_c is not None:
                    c = next_c
                else:
                    # check if we can jump gap of 1 row
                    gap_found = False
                    if r + 1 < num_rows:
                        for offset in [0, 1, -1, 2, -2]:
                            if grid[r+1][c+offset] in ['|', '│', '+']:
                                c = c + offset
                                r = r + 1
                                gap_found = True
                                break
                    if not gap_found:
                        return None
        return None

    # Function to find direct children of a person box
    def find_children(box):
        r1, r2, c1, c2 = box['r1'], box['r2'], box['c1'], box['c2']
        # 1. Find the parent vertical line on row r2 + 1 inside [c1, c2]
        c_parent = None
        for col in range(c1, c2 + 1):
            if grid[r2 + 1][col] in ['|', '│', '+']:
                c_parent = col
                break
        if c_parent is None:
            # try r2 + 2 or search a bit wider
            for col in range(c1 - 2, c2 + 3):
                if grid[r2 + 1][col] in ['|', '│', '+']:
                    c_parent = col
                    break
        if c_parent is None:
            return []

        # 2. Trace parent line down until we hit a horizontal connector line
        # A horizontal connector row has several horizontal characters like '-', '~', '_'
        r_h = None
        c_curr = c_parent
        for r in range(r2 + 1, num_rows):
            # Check if this row is a horizontal connector line
            # It should have horizontal characters at and around c_curr
            # Let's count horizontal characters in [c_curr - 3, c_curr + 3]
            h_count = sum(1 for col in range(c_curr - 3, c_curr + 4) if grid[r][col] in ['-', '~', '_', '+'])
            if h_count >= 3:
                r_h = r
                break
            # update c_curr if vertical line drifts
            next_c = None
            for offset in [0, 1, -1, 2, -2]:
                if grid[r][c_curr + offset] in ['|', '│', '+']:
                    next_c = c_curr + offset
                    break
            if next_c is not None:
                c_curr = next_c
            else:
                break

        if r_h is None:
            return []

        # 3. Find the column range of the horizontal line on row r_h
        # We allow 1-2 character gaps (spaces) in the horizontal line due to degradation
        col_min = c_curr
        while col_min > 0:
            # check if there's horizontal character in the next few columns to the left
            found_h = False
            for step in range(1, 4):
                if col_min - step >= 0 and grid[r_h][col_min - step] in ['-', '~', '_', '+']:
                    col_min -= step
                    found_h = True
                    break
            if not found_h:
                break

        col_max = c_curr
        while col_max < max_cols:
            found_h = False
            for step in range(1, 4):
                if col_max + step < max_cols and grid[r_h][col_max + step] in ['-', '~', '_', '+']:
                    col_max += step
                    found_h = True
                    break
            if not found_h:
                break

        # 4. On row r_h + 1, find all vertical lines starting within [col_min, col_max]
        children_boxes = []
        r_next = r_h + 1
        col = col_min
        while col <= col_max:
            if grid[r_next][col] in ['|', '│', '+']:
                # Found a vertical line! Trace it down to find the child box
                child = trace_vertical_line_down(r_next, col)
                if child:
                    if child not in children_boxes and child['name'] != box['name']:
                        children_boxes.append(child)
                # skip adjacent vertical columns to avoid duplicate tracing
                while col <= col_max and grid[r_next][col] in ['|', '│', '+']:
                    col += 1
            else:
                col += 1

        return children_boxes

    # Let's test finding children of Przemysław Kurczab
    p_kurczab = None
    for b in boxes:
        if b['name'] == 'Przemysław Kurczab':
            p_kurczab = b
            break

    if p_kurczab:
        children = find_children(p_kurczab)
        print(f"\nChildren of Przemysław Kurczab:")
        for ch in children:
            print(f"- {ch['name']} at box {ch['r1']},{ch['r2']},{ch['c1']},{ch['c2']}")
            # find grandchildren
            grandchildren = find_children(ch)
            print(f"  Grandchildren ({len(grandchildren)}): {[g['name'] for g in grandchildren]}")
            # find great-grandchildren
            for g in grandchildren:
                gg = find_children(g)
                print(f"    Great-grandchildren of {g['name']} ({len(gg)}): {[x['name'] for x in gg]}")

if __name__ == "__main__":
    solve()

