import re
import csv

def solve():
    with open("/app/dataset/genealogy_trees.txt", "r") as f:
        lines = [line.rstrip("\r\n") for line in f]

    num_rows = len(lines)
    max_cols = max(len(l) for l in lines)
    grid = [l + " " * (max_cols - len(l)) for l in lines]

    # Load people
    people = {}
    with open("/app/dataset/people_accounts.csv", "r") as f:
        reader = csv.reader(f)
        header = next(reader)
        for row in reader:
            if len(row) >= 3:
                first = row[0].strip()
                last = row[1].strip()
                balance = int(row[2].strip())
                people[f"{first} {last}"] = balance

    # Locate all boxes in the family tree
    boxes = []
    box_by_name = {}

    for name in people:
        first, last = name.split(maxsplit=1)
        found = False
        for r in range(num_rows):
            line = grid[r]
            if first in line:
                idx = -1
                while True:
                    idx = line.find(first, idx + 1)
                    if idx == -1:
                        break
                    # check last_name proximity
                    for r_offset in [-1, 0, 1]:
                        nr = r + r_offset
                        if 0 <= nr < num_rows:
                            nline = grid[nr]
                            if last in nline:
                                l_idx = nline.find(last)
                                if abs(idx - l_idx) < 15:
                                    # Found the name!
                                    # Determine c1 (left boundary)
                                    c1 = None
                                    for col in range(idx, max(-1, idx - 6), -1):
                                        if grid[r][col] in ['|', '│']:
                                            c1 = col
                                            break
                                    if c1 is None:
                                        c1 = idx - 2

                                    # Determine c2 (right boundary)
                                    name_end = max(idx + len(first), l_idx + len(last))
                                    c2 = None
                                    for col in range(name_end, min(max_cols, name_end + 6)):
                                        if grid[r][col] in ['|', '│']:
                                            c2 = col
                                            break
                                    if c2 is None:
                                        c2 = name_end + 2

                                    # Determine r1 and r2 (top/bottom boundaries)
                                    r1 = min(r, nr) - 1
                                    r2 = max(r, nr) + 1

                                    box_info = {
                                        'name': name,
                                        'r1': r1, 'r2': r2, 'c1': c1, 'c2': c2
                                    }
                                    if name not in box_by_name:
                                        boxes.append(box_info)
                                        box_by_name[name] = box_info
                                    found = True
                                    break
                    if found:
                        break
                if found:
                    break

    print(f"Total successfully mapped boxes: {len(boxes)}")

    # Function to check which box a point is inside (inclusive of boundary lines)
    def find_box_at(r, c):
        # A box is rows r1+1 to r2-1, columns c1+1 to c2-1.
        # But we also include the boundaries to be safe.
        for b in boxes:
            if b['r1'] <= r <= b['r2'] and b['c1'] <= c <= b['c2']:
                return b
        return None

    # Function to follow a vertical line down to find a child box
    def trace_vertical_line_down(r_start, c_start):
        c = c_start
        for r in range(r_start, num_rows):
            # Check if we are inside any box
            # But wait! A box top is at b['r1']. If we touch r = b['r1'] at column c in [b['c1'], b['c2']],
            # we are entering the box!
            for b in boxes:
                # If we hit the top boundary of a box b, or go inside it
                if b['r1'] <= r <= b['r2'] and b['c1'] <= c <= b['c2']:
                    return b
            # Follow vertical characters
            if grid[r][c] not in ['|', '│', '+']:
                # search nearby columns for line drift
                next_c = None
                for offset in [1, -1, 2, -2]:
                    if grid[r][c + offset] in ['|', '│', '+']:
                        next_c = c + offset
                        break
                if next_c is not None:
                    c = next_c
                else:
                    # check for gap jump
                    gap_found = False
                    if r + 1 < num_rows:
                        for offset in [0, 1, -1, 2, -2]:
                            if grid[r+1][c+offset] in ['|', '│', '+']:
                                c = c + offset
                                r = r + 1
                                gap_found = True
                                break
                    if not gap_found:
                        return None
        return None

    # Function to find direct children of a person box
    def find_children(box):
        r1, r2, c1, c2 = box['r1'], box['r2'], box['c1'], box['c2']
        # Find parent vertical line going down from bottom of box r2
        c_parent = None
        for col in range(c1, c2 + 1):
            if grid[r2 + 1][col] in ['|', '│', '+']:
                c_parent = col
                break
        if c_parent is None:
            for col in range(c1 - 2, c2 + 3):
                if grid[r2 + 1][col] in ['|', '│', '+']:
                    c_parent = col
                    break
        if c_parent is None:
            return []

        # Trace parent line down until we hit a horizontal connector line
        r_h = None
        c_curr = c_parent
        for r in range(r2 + 1, num_rows):
            # Look for horizontal character count around c_curr
            h_count = sum(1 for col in range(c_curr - 3, c_curr + 4) if grid[r][col] in ['-', '~', '_', '+'])
            if h_count >= 3:
                r_h = r
                break
            # follow drift
            next_c = None
            for offset in [0, 1, -1, 2, -2]:
                if grid[r][c_curr + offset] in ['|', '│', '+']:
                    next_c = c_curr + offset
                    break
            if next_c is not None:
                c_curr = next_c
            else:
                break

        if r_h is None:
            return []

        # Find boundaries of horizontal connector line on row r_h
        col_min = c_curr
        while col_min > 0:
            found_h = False
            for step in range(1, 4):
                if col_min - step >= 0 and grid[r_h][col_min - step] in ['-', '~', '_', '+']:
                    col_min -= step
                    found_h = True
                    break
            if not found_h:
                break

        col_max = c_curr
        while col_max < max_cols:
            found_h = False
            for step in range(1, 4):
                if col_max + step < max_cols and grid[r_h][col_max + step] in ['-', '~', '_', '+']:
                    col_max += step
                    found_h = True
                    break
            if not found_h:
                break

        # On row r_h + 1, find all vertical lines starting within [col_min, col_max]
        children_boxes = []
        r_next = r_h + 1
        col = col_min
        while col <= col_max:
            if grid[r_next][col] in ['|', '│', '+']:
                child = trace_vertical_line_down(r_next, col)
                if child:
                    if child not in children_boxes and child['name'] != box['name']:
                        children_boxes.append(child)
                # skip adjacent vertical columns
                while col <= col_max and grid[r_next][col] in ['|', '│', '+']:
                    col += 1
            else:
                col += 1

        return children_boxes

    # Let's verify the lineage of Dawid Majtyka up to great-great-grandparent
    # We find parent, grandparent, great-grandparent, great-great-grandparent
    # by tracing parent up.
    # To trace parent up: we can find which parent box has this person as child!
    # Let's map parent for all boxes
    parent_map = {}
    for b in boxes:
        children = find_children(b)
        for child in children:
            parent_map[child['name']] = b

    target = 'Dawid Majtyka'
    curr = target
    lineage = []
    for _ in range(5):
        if curr in box_by_name:
            lineage.append(curr)
            parent_box = parent_map.get(curr)
            if parent_box:
                curr = parent_box['name']
            else:
                break
        else:
            break

    print(f"\nLineage of {target}: {' -> '.join(lineage)}")

    if len(lineage) >= 5:
        ancestor_name = lineage[4]
        print(f"Great-great-grandparent of {target} is {ancestor_name}")
        ancestor_box = box_by_name[ancestor_name]

        # Direct children of ancestor
        direct_children = find_children(ancestor_box)
        print(f"\nDirect children of {ancestor_name}:")
        total_balance_sum = 0
        for child in direct_children:
            # find grandchildren of ancestor (children of this child)
            grandchildren = find_children(child)
            num_grandchildren = len(grandchildren)
            print(f"- {child['name']}: grandchildren count={num_grandchildren}, list={[g['name'] for g in grandchildren]}")
            if num_grandchildren > 1:
                # Add account balance
                bal = people.get(child['name'], 0)
                print(f"  -> Satisfies condition (>1 grandchildren)! Account balance: {bal}")
                total_balance_sum += bal
            else:
                print(f"  -> Does NOT satisfy condition.")
        print(f"\nTotal sum of account balances of direct children with >1 grandchildren: {total_balance_sum}")
    else:
        print("\nCould not trace 4 generations above Dawid Majtyka!")

if __name__ == "__main__":
    solve()

